import QRCode from 'qrcode';
import {menuEditor,menuEditorRow,parseMenuEditor} from './menu-editor.mjs';
import {queueSummary,publicMenu} from './domain.mjs';
import {orderMenuView,cartView} from './order-view.mjs';
import {createCopilotClient,COPILOT_DEMO_STORAGE_KEY} from './client.mjs';
import {header,footer,serviceView,queueView,menuView,settingsView,guestView,trackingView,errorView,esc,tr,money,itemName} from './views.mjs';
import {intelligenceView,recipeForm,ingredientFields} from './cost-views.mjs';
import {mountMotion,revealOnChange} from './motion.mjs';
import {createAiDemoState,updateAiDemo,summarizeAiDemo,answerAiDemo} from './ai-demo.mjs';
import {aiView} from './ai-view.mjs';
import {menuImportView} from './menu-import-view.mjs';
import {parseMenuCsv,mergeMenuImport,createDemoMenuDraft} from './menu-import.mjs';
import {prepareDishPhoto} from './menu-photo-client.mjs';
import {menuDraftFingerprint,assertMenuDraftCurrent} from './menu-draft.mjs';
import {mergeDishEdit} from './dish-editor.mjs';
import {createPanelMotion} from '../panel-motion.mjs';
import {mountReceiptStory} from './receipt-story.mjs';
const path=location.pathname.replace(/\/$/,''),demo=path.endsWith('/demo'),guest=path.startsWith('/menu'),params=new URLSearchParams(location.search);
const client=createCopilotClient({demo}),main=document.querySelector('#cp-main'),dialog=document.querySelector('#cp-dialog'),toastEl=document.querySelector('#cp-toast');
let language='en';try{language=localStorage.getItem('soi-copilot-language')==='th'?'th':'en';}catch{}
let state=null,menuData=null,view='intelligence',filter='all',category='all',table=(params.get('table')||'Table 03').slice(0,40),menuKey=params.get('shop')||(demo?'demo':''),trackingToken='',tracking=null,cart=Object.create(null),manual=false,orderNote='',pendingId=null,busy=false,toastTimer,qrTimer,returnFocus=null,receipts=[],workspaceClient=null,ocrController=null,receiptDraft=null,receiptFile=null;
const t=(en,th)=>tr(language,en,th),uuid=()=>crypto.randomUUID(),countCart=()=>Object.values(cart).reduce((a,b)=>a+b,0);
let aiState=demo?createAiDemoState():null,aiMessages=[],aiDraft='',aiAsking=false;
let menuImportSource='photo',menuImportPreview='',menuDraftBaseline='';
const photoPreviews=new Set();
const photoOptions=()=>({demo,photoUrl:photo=>client.photoUrl(photo)});
function clearPhotoPreviews(){for(const url of photoPreviews)URL.revokeObjectURL(url);photoPreviews.clear();menuImportPreview='';}
function previewPhoto(blob){const url=URL.createObjectURL(blob);photoPreviews.add(url);return url;}
function hydrateMenuPhotos(data){return {...data,menu:data.menu.map(item=>({...item,photoUrl:client.photoUrl(item.photo,state?.publicKey||menuKey)}))};}
const panelBackground=[main,document.querySelector('#cp-header'),document.querySelector('#cp-footer')];
let panelMotion=createPanelMotion({dialog,background:panelBackground}),stopReceiptStory=()=>{},returnDishId='';
let stopMotion=mountMotion(document);
function notify(message,error=false){clearTimeout(toastTimer);toastEl.textContent=message;toastEl.hidden=false;toastEl.dataset.error=String(error);toastTimer=setTimeout(()=>{toastEl.hidden=true;},error?9000:5000);}
function formError(error){const old=dialog.querySelector('[data-form-error]');old?.remove();const p=document.createElement('p');p.className='cp-error';p.dataset.formError='';p.setAttribute('role','alert');p.textContent=error.message||String(error);if(dialog.open)dialog.prepend(p);else notify(p.textContent,true);}
function chrome(){document.documentElement.lang=language;document.querySelector('#cp-header').innerHTML=header({language,demo,guest,view});document.querySelector('#cp-footer').innerHTML=footer({language,demo,guest});}
function viewFromHash(){const value=location.hash.slice(1);return ['intelligence','order','ai','service','menu','settings'].includes(value)?value:'intelligence';}
function render({animate=true}={}){
 stopReceiptStory();stopReceiptStory=()=>{};
 chrome();
 if(guest){main.innerHTML=tracking?trackingView({order:tracking,language,demo}):guestView({data:menuData,language,demo,category,cartCount:countCart(),table});}
 else if(view==='order'){
  menuKey=demo?'demo':state.publicKey;menuData=hydrateMenuPhotos(publicMenu(state));
  if(category!=='all'&&!menuData.menu.some(m=>m.category===category))category='all';const available=new Set(menuData.menu.map(m=>m.id));for(const id of Object.keys(cart))if(!available.has(id))delete cart[id];
  main.innerHTML=orderMenuView({state,data:menuData,language,demo,category,cart,table,tracking});drawQr();
 }else if(view==='ai'){
  main.innerHTML=aiView({language,demo,aiState,summary:demo?summarizeAiDemo(aiState,{copilotState:state}):null,messages:aiMessages});
  const input=main.querySelector('#cp-ai-form [name="question"]');if(input)input.value=aiDraft;
 }else{const args={state,language,demo,filter,table};main.innerHTML=({intelligence:intelligenceView,service:serviceView,menu:menuView,settings:settingsView})[view](args);if(view==='menu')drawQr();}
 revealOnChange(document,{animate});
 if(!guest&&view==='ai'&&demo)stopReceiptStory=mountReceiptStory(main);
}
function menuUrl(){const url=new URL('/menu'+(demo?'/demo':''),location.origin);url.searchParams.set('shop',demo?'demo':state.publicKey);url.searchParams.set('table',table);return url.href;}
async function drawQr(){const canvas=document.querySelector('#cp-qr'),link=document.querySelector('#cp-menu-link');if(!canvas||!state)return;const url=menuUrl();link.href=url;try{await QRCode.toCanvas(canvas,url,{width:208,margin:4,errorCorrectionLevel:'M',color:{dark:'#123a31',light:'#ffffff'}});}catch{notify(t('The QR could not be drawn. Use the menu link.','แสดง QR ไม่สำเร็จ โปรดใช้ลิงก์เมนู'),true);}}
async function initialize(){try{if(guest){if(!menuKey)throw Error(t('Open the menu using your merchant’s table QR.','กรุณาเปิดเมนูด้วย QR ของร้าน'));menuData=await client.menu(menuKey);const hash=location.hash.match(/^#order=([a-f0-9]{32})$/);trackingToken=hash?.[1]||'';if(trackingToken)tracking=await client.track(menuKey,trackingToken);}else{state=await client.load();view=viewFromHash();}render();if(client.notice)notify(client.notice);}catch(error){chrome();main.innerHTML=errorView(error,language,demo);}}
async function refresh({quiet=false}={}){if(busy||dialog.open)return;if(quiet&&view==='ai'&&main.contains(document.activeElement)&&document.activeElement.closest('button,a,input,textarea,select,summary'))return;try{if(guest){if(trackingToken){tracking=await client.track(menuKey,trackingToken);render({animate:false});}else {const next=await client.menu(menuKey),changed=JSON.stringify(next)!==JSON.stringify(menuData);menuData=next;if(changed){const available=new Set(next.menu.map(m=>m.id));for(const id of Object.keys(cart))if(!available.has(id))delete cart[id];render({animate:false});}}}else{const next=await client.load(),changed=!state||next.revision!==state.revision;state=next;if(view==='service'){const container=document.querySelector('#cp-queue');if(container){const focused=document.activeElement;const selector=focused?.dataset.order?`[data-order="${focused.dataset.order}"][data-status="${focused.dataset.status}"]`:null;container.innerHTML=queueView({state,language,filter});if(selector)container.querySelector(selector)?.focus({preventScroll:true});revealOnChange(document,{animate:false});}const summary=queueSummary(state);for(const [key,value] of [['count',String(summary.activeOrders).padStart(2,'0')],['offline',summary.offlineOrders],['online',summary.onlineOrders]])document.querySelector('[data-hero-'+key+']')?.replaceChildren(String(value));}else if(view==='order'){menuKey=demo?'demo':state.publicKey;if(trackingToken)tracking=await client.track(menuKey,trackingToken);if(changed||tracking)render({animate:false});}else if(changed&&view!=='settings'&&view!=='menu')render({animate:false});}if(!quiet)notify(t('Up to date.','ข้อมูลเป็นปัจจุบันแล้ว'));}catch(error){if(!quiet)notify(error.message,true);}}
function dishSource(id){return [...main.querySelectorAll('[data-dish-source]')].find(node=>node.dataset.dishSource===id);}
function openDialog(title,body,transition={}){if(!dialog.open)returnFocus=document.activeElement;returnDishId=transition.dishId||'';dialog.innerHTML=`<div class="cp-dialog-header"><h2 id="cp-dialog-title">${esc(title)}</h2><button class="cp-close" type="button" data-action="close-dialog" aria-label="${t('Close','ปิด')}">×</button></div>${body}`;dialog.showModal();panelMotion.enter({source:transition.source,target:dialog.querySelector('[data-dish-hero]'),resolveSource:transition.dishId?()=>dishSource(transition.dishId):undefined});}
function closeDialog(){panelMotion.prepareClose();dialog.close();ocrController?.abort();ocrController=null;returnFocus?.isConnected&&returnFocus.focus({preventScroll:true});}
function setBusy(value){busy=value;dialog.setAttribute('aria-busy',String(value));dialog.querySelectorAll('button[type="submit"]').forEach(b=>b.disabled=value);}
async function mutate(action,payload){const result=await client.mutate(action,payload);state=result.state;return result;}
function openOrder(isManual=false){manual=isManual;if(isManual){pendingId=null;cart=Object.create(null);}const catalog=isManual?state.menu.filter(m=>m.available):menuData.menu;const fields=catalog.filter(m=>isManual||cart[m.id]).map(m=>`<label class="cp-order-line"><span>${esc(itemName(m,language))}<small data-unit-price="${m.id}">${money(m.storePriceCents,language)}</small></span><input name="qty-${m.id}" data-cart-qty="${m.id}" type="number" min="0" max="20" step="1" value="${cart[m.id]||0}" aria-label="${esc(t('Quantity for ','จำนวน ')+itemName(m,language))}"></label>`).join('');openDialog(isManual?t('Add an order','เพิ่มออเดอร์'):t('Review your order','ตรวจสอบออเดอร์'),`<form id="cp-order-form" class="cp-form">${isManual?`<label class="cp-field">${t('Channel','ช่องทาง')}<select name="channel"><option value="offline">${t('In-store','หน้าร้าน')}</option><option value="online">${t('Online — manually entered','ออนไลน์ — เพิ่มด้วยตนเอง')}</option></select></label>`:''}<label class="cp-field">${t('Table or collection label','ชื่อโต๊ะหรือจุดรับ')}<input name="table" value="${esc(isManual?'':table)}" maxlength="40" required></label><div class="cp-cart-lines">${fields}</div><label class="cp-field">${t('Kitchen note (optional)','หมายเหตุถึงครัว (ไม่บังคับ)')}<textarea name="note" rows="2" maxlength="300" placeholder="${t('For urgent allergies, speak directly with staff.','หากแพ้อาหาร กรุณาแจ้งพนักงานโดยตรง')}">${esc(isManual?'':orderNote)}</textarea></label><div class="cp-cart-total"><span>${t('Order value','มูลค่าออเดอร์')}</span><strong id="cp-cart-total">${money(0,language)}</strong></div><p class="cp-note">${demo?t('Simulated order. No food is prepared and no payment is taken.','ออเดอร์จำลอง ไม่มีการเตรียมอาหารหรือเรียกเก็บเงิน'):t('Send to the kitchen. Payment is arranged directly with the merchant.','ส่งถึงครัว ชำระเงินกับร้านค้าโดยตรง')}</p><button class="cp-button" type="submit">${isManual?t('Add to queue','เพิ่มเข้าคิว'):t('Send to kitchen','ส่งให้ครัว')} →</button></form>`);updateCartTotal();}
function updateCartTotal(){const form=document.querySelector('#cp-order-form');if(!form)return;const catalog=manual?state.menu:menuData.menu,online=form.elements.channel?.value==='online';let total=0;for(const m of catalog){const input=form.querySelector(`[data-cart-qty="${m.id}"]`),qty=Number(input?.value||0);const unitPrice=online?m.onlinePriceCents:m.storePriceCents;form.querySelector('[data-unit-price="'+m.id+'"]')?.replaceChildren(money(unitPrice,language));total+=unitPrice*Math.max(0,Math.min(20,qty||0));}document.querySelector('#cp-cart-total').textContent=money(total,language);}
function updateCartBar(){
 const panel=document.querySelector('#cp-embedded-cart');
 if(panel){const focused=document.activeElement,add=focused?.dataset.add,remove=focused?.dataset.remove,inside=panel.contains(focused);panel.innerHTML=cartView({data:menuData,language,demo,cart});if(inside&&(add||remove)){const target=[...panel.querySelectorAll('button')].find(b=>add?b.dataset.add===add:b.dataset.remove===remove);(target||[...document.querySelectorAll('[data-add]')].find(b=>b.dataset.add===(remove||add))||panel.querySelector('[data-action="review-cart"]'))?.focus({preventScroll:true});}}
 else {const el=document.querySelector('#cp-cart-count');if(el)el.textContent=String(countCart());const button=document.querySelector('[data-action="review-cart"]');if(button)button.disabled=!countCart();}
 for(const label of document.querySelectorAll('[data-selected]')){const n=cart[label.dataset.selected]||0;label.hidden=!n;label.textContent=n+' '+t('selected','ที่เลือก');}
 for(const button of document.querySelectorAll('[data-add]'))button.disabled=!menuData?.shop.accepting||(cart[button.dataset.add]||0)>=20||countCart()>=50;
}
async function openRecipe(menuId){if(!state.menu.some(m=>m.id===menuId))throw Error(t('Archived recipes are read-only.','สูตรที่เก็บถาวรแก้ไขไม่ได้'));if(!demo){workspaceClient??=await import('../client.mjs');const w=await workspaceClient.loadWorkspace();if(w.capabilities?.storage!=='cloud')throw Error(t('Reconnect your private workspace before editing receipt-backed costs.','เชื่อมพื้นที่ส่วนตัวให้สำเร็จก่อนแก้ไขต้นทุนที่อ้างอิงใบซื้อ'));receipts=(w.state?.receipts||[]).filter(r=>r.status==='confirmed'&&r.kind==='purchase'&&r.reviewed&&r.source?.mode!=='simulated');}openDialog(t('Cost per plate / SKU','ต้นทุนต่อจาน / SKU'),recipeForm({state,menuId,receipts,language}));}
function openMenuEditor(items=state.menu,importing=false){menuDraftBaseline=menuDraftFingerprint(state.menu);openDialog(importing?t('Review your menu','ตรวจสอบเมนูของคุณ'):t('Edit menu and photos','แก้ไขเมนูและภาพ'),menuEditor(state,language,{items,importing,...photoOptions()}));dialog.querySelector('input,select')?.focus();}
function openDishEditor(id){if(guest||busy)return;const item=state.menu.find(item=>item.id===id);if(!item)return;menuDraftBaseline=menuDraftFingerprint(state.menu);openDialog(t('Edit dish','แก้ไขเมนูอาหาร'),menuEditor(state,language,{editSku:id,...photoOptions()}),{dishId:id,source:dishSource(id)});dialog.querySelector('input[name="name"]')?.focus({preventScroll:true});}
function openMenuImport(source='photo'){menuImportSource=source;openDialog(t('Import your menu','นำเข้าเมนูของคุณ'),menuImportView({language,demo,source,preview:menuImportPreview}));dialog.querySelector('[data-menu-source="'+source+'"]')?.focus();}
function choicePhoto(value){if(value.startsWith('generated:'))return {kind:'generated',key:value.slice(10)};if(value.startsWith('uploaded:'))return {kind:'uploaded',id:value.slice(9)};return null;}
function showDishPhoto(row,url){const image=row.querySelector('[data-photo-preview]'),empty=row.querySelector('[data-photo-empty]');image.hidden=!url;if(url)image.src=url;else image.removeAttribute('src');empty.hidden=!!url;}
async function uploadDishPhoto(input){
 const row=input.closest('[data-menu-item]'),file=input.files?.[0];if(!row||!file)return;if(busy){input.value='';notify(t('Wait for the current upload to finish.','รอให้อัปโหลดรายการปัจจุบันเสร็จก่อน'));return;}
 const select=row.querySelector('[name="photoChoice"]'),status=row.querySelector('[data-photo-status]');setBusy(true);row.dataset.photoPending='true';input.disabled=true;select.disabled=true;status.textContent=t('Preparing your photo…','กำลังเตรียมภาพ…');
 try{const blob=await prepareDishPhoto(file);if(!row.isConnected||!dialog.open)return;const result=await client.uploadPhoto(blob);state=result.state||client.getState()||state;if(!row.isConnected||!dialog.open)return;assertMenuDraftCurrent(menuDraftBaseline,state.menu);
  const value='uploaded:'+result.photo.id;for(const option of [...select.options])if(option.value.startsWith('uploaded:'))option.remove();const option=document.createElement('option');option.value=value;option.textContent=t('My uploaded photo','ภาพที่ฉันอัปโหลด');select.append(option);select.value=value;row.dataset.uploadedPreview=previewPhoto(blob);showDishPhoto(row,row.dataset.uploadedPreview);status.textContent=t('Photo ready. Save the menu to apply it.','ภาพพร้อมแล้ว บันทึกเมนูเพื่อใช้งาน');
 }catch(error){if(row.isConnected&&dialog.open){status.textContent=error.message;formError(error);}}finally{row.dataset.photoPending='false';input.disabled=false;select.disabled=false;input.value='';setBusy(false);}
}
function download(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function updateAi(action,value,focusId){if(!demo||!aiState)return;aiState=updateAiDemo(aiState,{action,value});render({animate:false});if(focusId)document.getElementById(focusId)?.focus({preventScroll:true});notify(t('Demo context updated. Ask the Advisor about this change.','อัปเดตบริบทเดโมแล้ว ถามผู้ช่วยเกี่ยวกับการเปลี่ยนแปลงนี้ได้'));}
async function askAi(question){
 if(!demo||!aiState||aiAsking)return;const content=String(question||'').trim().slice(0,1000);if(!content)return;
 aiAsking=true;try{state=await client.load();
 aiMessages=[...aiMessages,{id:uuid(),role:'user',content},answerAiDemo(content,aiState,language,{copilotState:state})].slice(-12);aiDraft='';render({animate:false});
 const input=main.querySelector('#cp-ai-form [name="question"]');input?.focus({preventScroll:true});
 main.querySelector('.cp-ai-messages')?.scrollTo({top:100000,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});
 }finally{aiAsking=false;}
}
function importDialog(){openDialog(t('Connect an order export','เชื่อมข้อมูลส่งออกออเดอร์'),`<form id="cp-import-form" class="cp-form"><p>${t('Upload a CSV from any system mapped to these five columns. SKU IDs must match your menu.','อัปโหลด CSV จากระบบใดก็ได้ที่จัดคอลัมน์ตามนี้ รหัส SKU ต้องตรงกับเมนู')}</p><code>order_id,channel,table,sku,quantity</code><p class="cp-note">${t('Channel: offline or online. Prices come from your menu; identical order IDs are safely deduplicated.','ช่องทาง: offline หรือ online ใช้ราคาจากเมนู รหัสออเดอร์ซ้ำจะไม่ถูกเพิ่มซ้ำ')}</p><label class="cp-field">CSV<input name="csv" type="file" accept=".csv,text/csv" required></label><button type="button" class="cp-link" data-action="csv-template">${t('Download example template','ดาวน์โหลดไฟล์ตัวอย่าง')} ↓</button><details><summary>${t('Menu SKU IDs','รหัส SKU เมนู')}</summary>${state.menu.map(m=>`<p><code>${m.id}</code> · ${esc(itemName(m,language))}</p>`).join('')}</details><button class="cp-button" type="submit">${t('Import orders','นำเข้าออเดอร์')}</button></form>`);}
async function receiptDialog(){if(demo){if(view==='ai'){render({animate:false});main.querySelector('#cp-ai-confirm')?.focus();}else location.hash='#ai';return;}openDialog(t('Read a supplier receipt','อ่านใบซื้อวัตถุดิบ'),`<form id="cp-ocr-form" class="cp-form"><p>${t('Read locally with our Thai / English receipt OCR. Review the fields before saving.','อ่านด้วย OCR ไทย / อังกฤษในเบราว์เซอร์ ตรวจสอบข้อมูลก่อนบันทึก')}</p><label class="cp-field">${t('Receipt photo (JPEG, PNG, WebP · up to 8 MB)','รูปใบซื้อ (JPEG, PNG, WebP · ไม่เกิน 8 MB)')}<input name="photo" type="file" accept="image/jpeg,image/png,image/webp" required></label><button class="cp-button" type="submit">${t('Read receipt','อ่านใบซื้อ')}</button><a class="cp-link" href="/versionc#advisor">${t('Full receipt workspace and manual entry','หน้าใบซื้อเต็มและกรอกข้อมูลเอง')} ↗</a></form>`);}
function showReceiptReview(){const r=receiptDraft;dialog.innerHTML=`<div class="cp-dialog-header"><h2 id="cp-dialog-title">${t('Confirm purchase fields','ยืนยันข้อมูลใบซื้อ')}</h2><button class="cp-close" data-action="close-dialog" aria-label="${t('Close','ปิด')}">×</button></div><form id="cp-receipt-form" class="cp-form"><p class="cp-note">${t('Only purchase receipts support ingredient costs. Check every amount against your original.','ใช้ใบซื้อวัตถุดิบเพื่อคำนวณต้นทุน ตรวจทุกจำนวนเทียบต้นฉบับ')}</p><label class="cp-field">${t('Supplier','ผู้ขาย')}<input name="merchant" value="${esc(r.merchant||'')}" maxlength="200"></label><label class="cp-field">${t('Date (optional)','วันที่ (ไม่บังคับ)')}<input type="date" name="date" value="${esc(r.date||'')}"></label><label class="cp-field">${t('Receipt total (THB; optional)','ยอดรวม (บาท; ไม่บังคับ)')}<input name="total" type="number" min="0" step=".01" value="${r.total??''}"></label>${r.items.map((i,n)=>`<fieldset data-receipt-line><legend>${t('Line','รายการ')} ${n+1}</legend><label class="cp-field">${t('Ingredient','วัตถุดิบ')}<input name="name" value="${esc(i.name)}" required maxlength="200"></label><div class="cp-form-pair">${[['quantity','Quantity','จำนวน'],['unitPrice','Unit price (THB)','ราคาต่อหน่วย (บาท)'],['lineTotal','Line total (THB)','ยอดรายการ (บาท)']].map(([key,en,th])=>`<label class="cp-field">${t(en,th)}<input name="${key}" type="number" min="0" step="${key==='quantity'?'.001':'.01'}" value="${i[key]??''}"></label>`).join('')}</div></fieldset>`).join('')}<details><summary>${t('Original OCR text','ข้อความ OCR ต้นฉบับ')}</summary><pre>${esc(r.text)}</pre></details><label class="cp-check"><input name="reviewed" type="checkbox" required>${t('I checked the purchase lines and amounts.','ตรวจสอบรายการซื้อและจำนวนเงินแล้ว')}</label><button class="cp-button" type="submit">${t('Confirm and map recipe','ยืนยันแล้วกำหนดสูตร')}</button></form>`;dialog.querySelector('input')?.focus();}

// One delegated handler keeps every rerender keyboard-operable without duplicate listeners.
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;try{if(el.dataset.editDish){openDishEditor(el.dataset.editDish);return;}if(el.dataset.menuSource){if(!busy)openMenuImport(el.dataset.menuSource);return;}if(el.dataset.aiPrompt){await askAi(el.dataset.aiPrompt);return;}if(el.dataset.aiAction==='confirm-receipt'){updateAi('confirm-receipt',true,'cp-ai-confirm');return;}if(el.dataset.filter){filter=el.dataset.filter;render({animate:false});document.querySelector('[data-filter="'+filter+'"]')?.focus({preventScroll:true});return;}if(el.dataset.category){category=el.dataset.category;render({animate:false});[...document.querySelectorAll('[data-category]')].find(b=>b.dataset.category===category)?.focus({preventScroll:true});return;}if(el.dataset.add){if(!menuData?.shop.accepting||countCart()>=50)return;cart[el.dataset.add]=Math.min(20,(cart[el.dataset.add]||0)+1);pendingId=null;updateCartBar();notify(t('Added to your order.','เพิ่มในออเดอร์แล้ว'));return;}if(el.dataset.remove){const id=el.dataset.remove;if(cart[id]>1)cart[id]--;else delete cart[id];pendingId=null;updateCartBar();return;}if(el.dataset.recipe){await openRecipe(el.dataset.recipe);return;}if(el.dataset.continueRecipe){closeDialog();await openRecipe(el.dataset.continueRecipe);return;}if(el.dataset.sampleSource){if(busy)return;busy=true;try{const r=await client.importSample(el.dataset.sampleSource);state=r.state||await client.load();render({animate:false});notify(t('Sample source mapped into the same SKU model.','เชื่อมแหล่งข้อมูลตัวอย่างกับรูปแบบ SKU เดียวกันแล้ว'));}finally{busy=false;}return;}if(el.dataset.status){if(busy)return;busy=true;try{await mutate('status',{orderId:el.dataset.order,status:el.dataset.status});render({animate:false});}finally{busy=false;}return;}if(el.dataset.cancel){openDialog(t('Cancel this order?','ยกเลิกออเดอร์นี้?'),`<p>${t('The kitchen will stop preparing this order. This does not issue a refund or change an external payment.','ครัวจะหยุดเตรียมออเดอร์นี้ การยกเลิกไม่ใช่การคืนเงินหรือแก้ไขการชำระภายนอก')}</p><button class="cp-button" data-confirm-cancel="${el.dataset.cancel}">${t('Cancel order','ยืนยันยกเลิก')}</button>`);return;}if(el.dataset.confirmCancel){if(busy)return;busy=true;try{await mutate('status',{orderId:el.dataset.confirmCancel,status:'cancelled'});closeDialog();render({animate:false});}finally{busy=false;}return;}
 const action=el.dataset.action;if(!action)return;
 if(action==='jump-cart'){e.preventDefault();const basket=document.querySelector('#cp-embedded-cart');basket?.scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});basket?.focus({preventScroll:true});return;}
 if(action==='close-dialog'){closeDialog();return;}
 if(action==='new-order'){openOrder(true);return;}if(action==='review-cart'){openOrder(false);return;}if(action==='edit-menu'){if(!busy)openMenuEditor();return;}if(action==='import-menu'){if(!busy)openMenuImport();return;}if(action==='receipt'){await receiptDialog();return;}if(action==='import-csv'){importDialog();return;}
 if(action==='refresh'||action==='refresh-tracking'){await refresh();return;}if(action==='retry'){await initialize();return;}
 if(action==='copy-menu'){await navigator.clipboard.writeText(menuUrl());notify(t('Menu link copied.','คัดลอกลิงก์เมนูแล้ว'));return;}
 if(action==='back-menu'){tracking=null;trackingToken='';history.replaceState(null,'',guest?location.pathname+location.search:'#order');menuData=await client.menu(menuKey);render();return;}
 if(action==='reset-demo'){openDialog(t('Restart the sample service?','เริ่มข้อมูลเดโมใหม่?'),`<p>${t('This replaces only this browser’s copilot demo records.','แทนที่เฉพาะข้อมูลเดโม Copilot ในเบราว์เซอร์นี้')}</p><button class="cp-button" data-action="confirm-reset">${t('Restart demo','เริ่มเดโมใหม่')}</button>`);return;}
 if(action==='confirm-reset'){state=await client.resetDemo();aiState=createAiDemoState();aiMessages=[];aiDraft='';tracking=null;trackingToken='';cart=Object.create(null);closeDialog();render({animate:false});return;}
 if(action==='add-ingredient'){const root=dialog.querySelector('#cp-recipe-rows'),n=root.children.length;if(n>=20)throw Error(t('Use up to 20 ingredients.','ใช้วัตถุดิบได้ไม่เกิน 20 รายการ'));root.insertAdjacentHTML('beforeend',ingredientFields({},n,receipts,language));root.lastElementChild.querySelector('input')?.focus();return;}
 if(action==='remove-ingredient'){el.closest('[data-ingredient]').remove();return;}
 if(action==='new-sku'){const rows=dialog.querySelector('#cp-menu-editor-rows');if(rows.children.length>=60)throw Error(t('Keep up to 60 menu items.','ใช้เมนูได้ไม่เกิน 60 รายการ'));rows.insertAdjacentHTML('beforeend',menuEditorRow({},language,{isNew:true,...photoOptions()}));rows.lastElementChild.querySelector('input')?.focus();return;}
 if(action==='menu-csv-template'){download('soi-menu-template.csv','sku,name,name_th,category,store_price,online_price,prep_minutes,station\nbasil-chicken,Basil chicken rice,ข้าวกะเพราไก่,Kitchen,65.00,85.00,7,hot\n','text/csv');return;}
 if(action==='csv-template'){download('soi-orders-template.csv','order_id,channel,table,sku,quantity\nPOS-1001,offline,Table 05,basil-chicken,2\nPOS-1001,offline,Table 05,thai-tea,1\nDEL-1002,online,Delivery 12,chicken-rice,1\n','text/csv');return;}
 if(action==='export-orders'){download('soi-copilot-records.json',JSON.stringify({exportedAt:new Date().toISOString(),basis:'Order records and current recipe estimates. No payment settlement.',menu:state.menu,costings:state.costings||{},orders:state.orders.map(({trackingToken,requestFingerprint,...o})=>o)},null,2),'application/json');}
 }catch(error){formError(error);}});
document.addEventListener('input',e=>{if(e.target.closest('#cp-ai-form')&&e.target.name==='question')aiDraft=e.target.value.slice(0,1000);if(e.target.id==='cp-qr-table'){const nextTable=e.target.value.slice(0,40);if(nextTable!==table)pendingId=null;table=nextTable;clearTimeout(qrTimer);qrTimer=setTimeout(drawQr,120);}if(e.target.closest('#cp-order-form')){pendingId=null;if(!manual&&e.target.name==='note')orderNote=e.target.value;if(!manual&&e.target.name==='table')table=e.target.value.slice(0,40);if(!manual&&e.target.dataset.cartQty){const n=Number(e.target.value);cart[e.target.dataset.cartQty]=Number.isFinite(n)?Math.max(0,Math.min(20,Math.floor(n))):0;}updateCartTotal();}});
document.addEventListener('change',async e=>{if(e.target.matches('[data-dish-photo]')){await uploadDishPhoto(e.target);return;}if(e.target.name==='photoChoice'){const row=e.target.closest('[data-menu-item]');if(row){showDishPhoto(row,e.target.value.startsWith('uploaded:')&&row.dataset.uploadedPreview?row.dataset.uploadedPreview:client.photoUrl(choicePhoto(e.target.value)));}return;}if(e.target.id==='cp-menu-source-photo'){const file=e.target.files?.[0];if(!file||busy)return;setBusy(true);try{const blob=await prepareDishPhoto(file);if(!dialog.open||!e.target.isConnected)return;menuImportPreview=previewPhoto(blob);const box=dialog.querySelector('.cp-menu-import-preview');if(box){const image=document.createElement('img');image.src=menuImportPreview;image.alt=t('Your selected menu photo','ภาพเมนูที่คุณเลือก');box.replaceChildren(image);}}catch(error){e.target.value='';if(e.target.isConnected&&dialog.open)formError(error);}finally{setBusy(false);}return;}if(e.target.id==='cp-ai-storage'){updateAi('storage',e.target.value,'cp-ai-storage');return;}if(e.target.id==='cp-ai-demand'){updateAi('demand',Number(e.target.value),'cp-ai-demand');return;}if(e.target.id==='cp-language'){language=e.target.value;try{localStorage.setItem('soi-copilot-language',language);}catch{}if(guest?!menuData:!state){initialize();return;}render({animate:false});document.querySelector('#cp-language')?.focus({preventScroll:true});return;}if(e.target.name==='source'&&e.target.closest('[data-ingredient]')){const row=e.target.closest('[data-ingredient]'),purchase=row.querySelector('[name="purchaseCost"]');purchase.readOnly=e.target.value!=='manual';if(purchase.readOnly){const [id,index]=e.target.value.split(':'),line=receipts.find(r=>r.id===id)?.items[Number(index)];if(line){row.querySelector('[name="ingredientName"]').value=line.name;purchase.value=line.lineTotal;}}}if(e.target.closest('#cp-order-form')){pendingId=null;updateCartTotal();}});
document.addEventListener('submit',async e=>{const form=e.target;if(!form.id.startsWith('cp-'))return;e.preventDefault();if(busy)return;setBusy(true);try{const data=new FormData(form);
 if(form.id==='cp-ai-form'){await askAi(data.get('question'));}
 if(form.id==='cp-menu-photo-form'){if(!demo)throw Error(t('Photo-to-menu AI is available as a simulation in the demo.','AI แปลงภาพเป็นเมนูมีให้ทดลองแบบจำลองในเดโม'));const draft=createDemoMenuDraft();const incoming=draft.items.map(item=>({...item,photo:data.get('imageStyle')==='upload'?null:item.photo}));openMenuEditor(mergeMenuImport(state.menu,incoming),true);}
 if(form.id==='cp-menu-csv-form'){const file=data.get('csv');if(!file?.size||file.size>50000)throw Error(t('Choose a menu CSV smaller than 50 KB.','เลือกไฟล์ CSV เมนูขนาดไม่เกิน 50 KB'));const text=await file.text();if(!form.isConnected||!dialog.open)return;openMenuEditor(parseMenuCsv(text,state.menu),true);}
 if(form.id==='cp-settings-form'){await mutate('settings',{name:data.get('name'),capacity:Number(data.get('capacity')),grabMenuUrl:data.get('grabMenuUrl'),paymentMethods:data.getAll('paymentMethods'),accepting:data.has('accepting')});render({animate:false});notify(t('Service settings saved.','บันทึกการตั้งค่าแล้ว'));}
 if(form.id==='cp-menu-form'){const items=parseMenuEditor(form);state=await client.load();if(!form.isConnected||!dialog.open)return;assertMenuDraftCurrent(menuDraftBaseline,state.menu);const catalog=form.dataset.editSku?mergeDishEdit(state.menu,form.dataset.editSku,items):items;await mutate('menu',{items:catalog});closeDialog();render({animate:false});notify(t('Menu and photos saved.','บันทึกเมนูและภาพแล้ว'));}
 if(form.id==='cp-order-form'){pendingId??=uuid();const items=[...form.querySelectorAll('[data-cart-qty]')].map(i=>({id:i.dataset.cartQty,quantity:Number(i.value)})).filter(i=>i.quantity>0);const payload={requestId:pendingId,table:String(data.get('table')),items,note:String(data.get('note'))};if(manual){await mutate('order',{...payload,channel:data.get('channel')});closeDialog();render({animate:false});}else{const response=await client.submit(menuKey,payload);tracking=response.order;trackingToken=response.trackingToken;cart=Object.create(null);orderNote='';table=payload.table;history.replaceState(null,'',guest?'#order='+trackingToken:'#order');closeDialog();if(!guest){try{state=await client.load();}catch{notify(t('Order sent. Refresh the merchant queue to see it.','ส่งออเดอร์แล้ว รีเฟรชคิวร้านเพื่อดูรายการ'));}}render();main.focus({preventScroll:true});}pendingId=null;}
 if(form.id==='cp-recipe-form'){const ingredients=[...form.querySelectorAll('[data-ingredient]')].map(row=>{const field=name=>row.querySelector(`[name="${name}"]`).value,source=field('source'),[receiptId,line]=source.split(':');return {name:field('ingredientName'),source:source==='manual'?(demo?'demo':'manual'):'receipt',purchaseCostCents:Math.round(Number(field('purchaseCost'))*100),purchaseQuantity:Number(field('purchaseQuantity')),portionQuantity:Number(field('portionQuantity')),unit:field('unit'),...(source==='manual'?{}:{receiptId,receiptLine:Number(line)})};});await mutate('costing',{menuId:form.dataset.menu,source:ingredients.some(i=>i.source==='receipt')?'receipt':demo?'demo':'manual',ingredients,packagingCents:Math.round(Number(data.get('packaging'))*100),otherVariableCents:Math.round(Number(data.get('other'))*100),onlineFeeBps:data.get('fee')===''?null:Math.round(Number(data.get('fee'))*100)});closeDialog();render({animate:false});notify(t('Recipe costs updated.','อัปเดตต้นทุนสูตรแล้ว'));}
 if(form.id==='cp-import-form'){const file=data.get('csv');if(!file?.size||file.size>50000)throw Error(t('Choose a CSV smaller than 50 KB.','เลือก CSV ขนาดไม่เกิน 50 KB'));const r=await client.importCsv(await file.text());state=r.state||await client.load();closeDialog();render({animate:false});notify(t('Orders imported; duplicate IDs were skipped.','นำเข้าออเดอร์แล้ว ข้ามรหัสที่ซ้ำ'));}
 if(form.id==='cp-ocr-form'){receiptFile=data.get('photo');ocrController=new AbortController();workspaceClient??=await import('../client.mjs');receiptDraft=await workspaceClient.readReceipt(receiptFile,{signal:ocrController.signal,onProgress:p=>notify(`${t('Reading receipt','กำลังอ่านใบซื้อ')} ${Math.round((p.progress||0)*100)}%`)});if(!receiptDraft.items.length)throw Error(t('No item lines were identified. Use the full receipt workspace for manual entry.','ไม่พบรายการสินค้า กรุณากรอกเองในหน้าใบซื้อเต็ม'));showReceiptReview();}
 if(form.id==='cp-receipt-form'){const value=v=>v===''?null:Number(v);receiptDraft={...receiptDraft,kind:'purchase',merchant:String(data.get('merchant'))||null,date:String(data.get('date'))||null,total:value(data.get('total')),items:[...form.querySelectorAll('[data-receipt-line]')].map(row=>{const f=n=>row.querySelector(`[name="${n}"]`).value;return {name:f('name'),quantity:value(f('quantity')),unitPrice:value(f('unitPrice')),lineTotal:value(f('lineTotal'))};})};await workspaceClient.saveReceipt(receiptDraft,receiptFile);closeDialog();await openRecipe(state.menu[0].id);}
 }catch(error){if(!guest)state=client.getState()||state;if(form.isConnected)formError(error);}finally{setBusy(false);}});
dialog.addEventListener('cancel',()=>{ocrController?.abort();ocrController=null;});
dialog.addEventListener('close',()=>{if(dialog.open)return;if(returnDishId){const source=dishSource(returnDishId);(source?.querySelector('[data-edit-dish]')||main.querySelector('[data-action="edit-menu"]')||main).focus({preventScroll:true});returnDishId='';}clearPhotoPreviews();ocrController?.abort();ocrController=null;if(!manual&&view==='order'){updateCartBar();drawQr();}});
window.addEventListener('hashchange',()=>{if(guest)return;if(busy){history.replaceState(null,'','#'+view);notify(t('Finish the current save before changing views.','รอให้บันทึกเสร็จก่อนเปลี่ยนหน้า'));return;}view=viewFromHash();if(state){render();main.focus({preventScroll:true});window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}});
window.addEventListener('storage',e=>{if(demo&&e.key===COPILOT_DEMO_STORAGE_KEY)refresh({quiet:true});});
function startPolling(){return setInterval(()=>{if(!document.hidden&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName))refresh({quiet:true});},15000);}let poll=startPolling();
window.addEventListener('pagehide',()=>{stopReceiptStory();panelMotion.dispose();clearPhotoPreviews();clearInterval(poll);clearTimeout(qrTimer);clearTimeout(toastTimer);ocrController?.abort();stopMotion();});
window.addEventListener('pageshow',e=>{if(e.persisted){panelMotion=createPanelMotion({dialog,background:panelBackground});if(dialog.open)panelMotion.enter();stopReceiptStory=mountReceiptStory(main);stopMotion=mountMotion(document);revealOnChange(document,{animate:false});poll=startPolling();refresh({quiet:true});}});
await initialize();
